<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$eventId=(int)($_GET['event_id']??0);$events=pg_query($conn,'SELECT id,title FROM events ORDER BY start_at DESC');$params=[];$where="WHERE (sa.time_in_evidence IS NOT NULL OR sa.time_out_evidence IS NOT NULL)";if($eventId){$params[]=$eventId;$where.=' AND e.id=$1';}$rows=$params?pg_query_params($conn,"SELECT sa.id,sa.time_in_at,sa.time_out_at,sa.time_in_evidence,sa.time_out_evidence,sa.time_in_face_detected,sa.time_out_face_detected,s.session_name,e.title,a.full_name,a.attendee_code FROM session_attendance sa JOIN event_sessions s ON s.id=sa.session_id JOIN events e ON e.id=s.event_id JOIN event_registrations r ON r.id=sa.registration_id JOIN attendees a ON a.id=r.attendee_id $where ORDER BY COALESCE(sa.time_out_at,sa.time_in_at) DESC",$params):pg_query($conn,"SELECT sa.id,sa.time_in_at,sa.time_out_at,sa.time_in_evidence,sa.time_out_evidence,sa.time_in_face_detected,sa.time_out_face_detected,s.session_name,e.title,a.full_name,a.attendee_code FROM session_attendance sa JOIN event_sessions s ON s.id=sa.session_id JOIN events e ON e.id=s.event_id JOIN event_registrations r ON r.id=sa.registration_id JOIN attendees a ON a.id=r.attendee_id $where ORDER BY COALESCE(sa.time_out_at,sa.time_in_at) DESC");admin_page_start('Photo Archive','photos');?>
<div class="hero"><div><h2><i class="fas fa-images"></i> Attendance Photo Archive</h2><p>Protected proof photos captured during session scans. Access is audit logged.</p></div></div><div class="card"><form method="get" class="form-grid"><div class="field full"><label>Event</label><select name="event_id" onchange="this.form.submit()"><option value="">All events</option><?php if($events):while($e=pg_fetch_assoc($events)):?><option value="<?=(int)$e['id']?>" <?=$eventId===(int)$e['id']?'selected':''?>><?=h($e['title'])?></option><?php endwhile;endif;?></select></div></form></div><div class="grid two-col"><?php if($rows):while($r=pg_fetch_assoc($rows)):foreach(['time_in'=>'Time In','time_out'=>'Time Out'] as $key=>$label):$path=$r[$key.'_evidence'];if(!$path)continue;?><article class="card"><img src="view.php?id=<?=(int)$r['id']?>&type=<?=$key?>" alt="Attendance evidence" style="width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:12px"><h3 style="margin-top:14px"><?=h($r['full_name'])?></h3><p class="help"><?=h($r['attendee_code'])?> · <?=h($r['title'])?> · <?=h(ucfirst($r['session_name']))?></p><span class="badge active"><i class="fas fa-user-check"></i>&nbsp; <?=$label?> · Face detected</span><div class="help" style="margin-top:8px"><?=h(date('M j, Y g:i:s A',strtotime($r[$key.'_at'])))?></div></article><?php endforeach;endwhile;endif;?></div><?php if(!$rows||pg_num_rows($rows)===0):?><div class="card empty">No photo evidence captured yet.</div><?php endif;admin_page_end();?>
